insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_joranda_gadi_seat','Joranda Gadi (Mahima Dharma Seat)','Odisha','Dhenkanal','Heritage','Joranda Gadi is the world headquarters of Mahima Dharma, a revolutionary 19th-century monotheistic and casteless spiritual movement founded by Mahima Gosain and celebrated by saint-poet Bhima Bhoi. The monastery complex features the Gadi Mandir, Dhuni Mandir (where a sacred eternal fire burns), and ascetic monks clad in tree bark.','20.8167','85.5833','needs_review','October – March','1',array['mahima dharma','aleha','casteless faith','sacred fire','dhenkanal','spirituality']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
