insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_saptasajya_hills','Saptasajya Hill Stream & Hermitage','Odisha','Dhenkanal','Nature','Saptasajya (''Seven Beds'') is a cluster of seven emerald hills located 12 km from Dhenkanal town. Mentioned in mythology as the retreat of the Saptarshis and a resting haven of Lord Rama during his exile, the mountain stream flows past temples of Rameswar, Astasambhu, and Lord Rama.','20.6167','85.5333','needs_review','October – March','1',array['seven hills','stream','ramayana','saptarshi','picnic','dhenkanal']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
