insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_udayagiri_monastery','Udayagiri Buddhist Monastery & Stepwell','Odisha','Jajpur','Heritage','Udayagiri (''Sunrise Hill'') is the most expansive monastery complex of the Diamond Triangle. Excavated by the ASI, it reveals Madhavapura Mahavihara with colossal seated Buddha statues, a stepped rock-cut ancient water well with stone arches, and stone inscriptions of Buddhist dharanis.','20.6333','86.2667','needs_review','October – March','1',array['buddhist monastery','diamond triangle','stepwell','stupas','7th century','heritage']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
