insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_lalitgiri_relics','Lalitgiri Relic Casket Stupa & Museum','Odisha','Cuttack','Heritage','Lalitgiri is the oldest and holiest site of Odisha''s Diamond Triangle. Chronologically spanning from Mauryan times (3rd century BC) to the 13th century AD, the hilltop stupa yielded four concentric sacred relic caskets (Khondalite, steatite, silver, and gold) containing sacred bone relics believed to be of Lord Gautama Buddha.','20.5833','86.25','needs_review','October – March','1',array['buddha relics','diamond triangle','3rd century bc','stupa','gold casket','museum']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
